const FNV_OFFSET_BASIS = 0xcbf29ce484222325n;
const FNV_PRIME = 0x100000001b3n;
const UINT64_MASK = 0xffffffffffffffffn;
const FIELD_SEPARATOR = '�';

export class Hasher {
  private state = FNV_OFFSET_BASIS;

  add(value: string): void {
    let state = this.state;
    for (let index = 0; index < value.length; index += 1) {
      state ^= BigInt(value.charCodeAt(index));
      state = (state * FNV_PRIME) & UINT64_MASK;
    }
    this.state = state;
  }

  field(value: string | number | boolean | undefined): void {
    this.add(value === undefined ? FIELD_SEPARATOR : `${value}${FIELD_SEPARATOR}`);
  }

  digest(): string {
    return this.state.toString(16).padStart(16, '0');
  }
}
